    public partial class Home
    {
        private string whatIsSD =
            @"Stjerneduggen er en lille, tryg pasningsordning i Aarup med plads til 4-5 børn. Her er hverdagen fyldt med leg, motorik, musik og dejlige oplevelser i naturen. Jeg lægger vægt på at skabe en rolig og hjemlig atmosfære, hvor der er tid til nærvær og til at følge hvert enkelt barns nysgerrighed og unikke udvikling. ";

        private string aboutMeP1 =
            @"Mit navn er Rikke, og jeg står bag pasningsordningen Stjerneduggen. Jeg bor sammen med min mand og vores to børn i Aarup. Jeg er uddannet pædagog med erfaring fra daginstitution og familieliv – og jeg brænder for at skabe et roligt, stabilt og kærligt miljø, hvor både børn og forældre kan føle sig hjemme. 

Jeg er selv glad for at bruge min krop og er ikke bange for at løbe stærkt, klatre i træer eller se lidt fjollet ud når vi leger en god leg. Det er vigtigt for mig at børnene oplever at der er plads til at te sig tosset og udfordre sin krop i trygge rammer. Jeg blev i 2023 uddannet motorikvejleder hos Vends Motorik og naturskole og har derfor en god viden om børns motoriske udvikling.";

        private string aboutMeP2 =
            @"Jeg er glad for musik og bruger det meget i mit arbejde. Jeg synger meget og spiller guitar (til husbehov) Jeg er desuden glad for at være kreativ ved enten at male, tegne, klippe/klistre eller hækle. 

Med Stjerneduggen ønsker jeg at tilbyde en lille, hjertevarm pasningsordning, hvor børn får lov til at vokse i deres eget tempo.";

        private string strategyP1 =
            @"I pasningsordningen Stjerneduggen vægter jeg både struktur og spontanitet højt. Det vigtigste er, at børnene får lov til at lege, lære og udvikle sig – og det sker bedst i trygge, glade rammer. 

Børn trives i det genkendelige og forudsigelige. Derfor har vi faste rutiner, spisetider og en naturlig rytme i løbet af dagen. Samtidig ved jeg, at børn også har brug for at kunne følge deres nysgerrighed og undersøge verden i nuet. Udvikling og læring kan ikke altid planlægges – og nogle dage skrider tiderne, fordi vi er opslugt af en leg, en regnorm eller en samtale der betyder noget. Det er en fin balance: Hvornår holder man fast i det planlagte – og hvornår giver man slip og følger strømmen? I Stjerneduggen forsøger jeg at lytte og være opmærksom, så hvert enkelt barn får de bedste forudsætninger for trivsel, læring og livsglæde. 

I Stjerneduggen får børnene lov til at prøve sig selv af. Det er vigtigt, at der er plads til den ""farlige leg"" – altså den leg, hvor man mærker suget i maven, balancerer lidt på kanten og opdager, hvad man kan og tør. Det handler ikke om at presse børn ud i noget de ikke er klar til – men at de får lov til at udforske grænser; både de fysiske og dem der sidder indeni. Det er her børn udvikler sig, finder styrke og lærer nyt om sig selv. Det er vigtigt at have øje for ar hvad det enkelte barn opfatter som farligt da dette kan være forskelligt og at der derfor er forskel på hvilken støtte det enkelte barn har behov for. Nogle børn skal klatre til toppen af det højeste træ for at mærke suget i maven, mens andre bliver rigeligt udfordret ved at træde op på den lavest siddende gren. Det er derfor vigtigt at have tanke for hvad den ""farlige leg"" er for det enkelte barn og hjælpe med for nogle, langsom at skubbe grænsen uden at overtræde den og for andre at holde igen når den ""farlige leg"" ikke kan blive farlig nok. 
Når et barn vover sig ud i det ukendte, står jeg altid klar. Jeg guider, støtter, hjælper og træder til, hvis noget bliver for svært. For det man ikke kan endnu, skal der være plads til at lære. 

Børnene vil blive inddraget i forskellige gøremål, som bagning, madlavning, rengøring og lignende. For børn er det vi ser som kedelige voksen-opgaver, en vigtig læringsplatform. Da det er med til at lærer dem både gode vaner og vigtige færdigheder til deres senere liv. Det er desuden godt for børns selvværd at blive inddraget da det giver dem en følelse af vigtighed og uundværlighed i et fællesskab. Opgaverne vil dog altid være legende og i børnehøjde, for at børnene får den gode læring om for eksempel hygiejne og madlavning, men i sjove og legende rammer. Eksempel: Kom børn nu skal vi give legetøjet skumbad. 

I hverdagen lægger jeg vægt på: ";

        private string aboutNamingSd =
            @" Navnet Stjerneduggen er valgt med hjertet. Det vækker billeder af stjernelys, der daler stille ned og lægger sig som dug i græsset – et magisk øjeblik, som kun det nysgerrige barneøje rigtigt ser. For mig symboliserer det den ro, det nærvær og den fordybelse, jeg ønsker at give børnene. Her skal der være plads til at gå i sit eget tempo, opdage verden i det små og blive guidet – ikke skubbet – i sin udvikling. Barndommen er ikke et kapløb, men en tid til at være lige præcis dét, man er: barn. ";

        private string poem =
            @"Et blad bliver til en tallerken, 
en pind bliver til et sværd, 
og midt i planlagte aktiviteter 
opstår der små mirakler uden manuskript. 

En trøstet tåre. Et nyopfundet spil. 
En hånd, der rækker ud, fordi det føles rigtigt. 
Livet i børnehøjde følger rytmen som et hjerte, 
men springer alligevel i alle retninger. 

Det er her idyllen bor – 
ikke i det perfekte program, 
men i mødet mellem ramme og frihed, 
mellem klokken og nu’et, 
mellem verden og legen. ";


    }
